        connect(fn.doorNGal_e_m, fn.doorNGal_e_n);

        // North Gallery Internal Grid with bench flanking bypasses
        fn.nGal_w_n33 = addNode( 2.0, y, -33.0, fl, 'nGal_w_n33');
